#![cfg(test)]
//! The digest of a run context and the digest of a suite entry, against the independent vectors
//! of the oracle and against what each digest leaves out.

use std::str::FromStr;

use candler_schemas::evaluation::{
    ContextArtifact, ContextRaw, ContextRef, EvaluateParams, RunContext, SuiteEntry,
};
use candler_schemas::primitives::{Digest, FieldPath, Name, RelPath, RunKey};
use candler_schemas::raw::StreamName;
use candler_schemas::values::JsonValue;
use serde_json::Value;

/// The vectors of `context_digest.toml`, generated by Python with the `rfc8785` package.
const CONTEXT_VECTORS: &str =
    include_str!("../../../candler-core/tests/oracle/vectors/context_digest.toml");

/// The vectors of `suite_entry_digest.toml`, generated by Python with the `rfc8785` package.
const ENTRY_VECTORS: &str =
    include_str!("../../../candler-core/tests/oracle/vectors/suite_entry_digest.toml");

/// A digest of 64 hex digits that repeats `digit`.
fn digest(digit: char) -> Digest {
    let hex: String = std::iter::repeat_n(digit, 64).collect();
    // BORROW: explicit .as_str() instead of Deref coercion
    Digest::from_hex(hex.as_str()).expect("a digest")
}

/// The vectors of a file, as tables.
fn vectors(text: &str) -> Vec<toml::Table> {
    let table: toml::Table = toml::from_str(text).expect("the vector file is TOML");
    // INDEX: both vector files hold a `vector` array
    table["vector"]
        .as_array()
        .expect("the vectors are an array")
        .iter()
        // BORROW: .clone() makes each vector an owned table
        .map(|vector| vector.as_table().expect("a vector is a table").clone())
        .collect()
}

/// An edit of the parts of the base context.
type Edit = fn(&mut Parts);

/// The parts of a context that a case changes one at a time.
#[derive(Clone)]
struct Parts {
    root: String,
    trace: Option<String>,
    raw: Vec<(String, String)>,
    artifacts: Vec<(String, String, Digest)>,
    snapshots: Vec<(String, String, Digest)>,
    inputs: Vec<(String, String, Digest)>,
    metadata: Vec<(String, Value)>,
}

impl Parts {
    /// A context with one of each part.
    fn base() -> Self {
        Self {
            // BORROW: .to_owned() makes the owned text the part keeps
            root: "/runs/a".to_owned(),
            // BORROW: .to_owned() makes the owned text the part keeps
            trace: Some("/runs/a/trace.jsonl".to_owned()),
            // BORROW: .to_owned() makes the owned text each pair keeps
            raw: vec![("stdout".to_owned(), "/runs/a/raw/stdout".to_owned())],
            artifacts: vec![(
                // BORROW: .to_owned() makes the owned text the triple keeps
                "outputs/plan.json".to_owned(),
                // BORROW: .to_owned() makes the owned text the triple keeps
                "/runs/a/outputs/plan.json".to_owned(),
                digest('1'),
            )],
            snapshots: vec![(
                // BORROW: .to_owned() makes the owned text the triple keeps
                "catalog".to_owned(),
                // BORROW: .to_owned() makes the owned text the triple keeps
                "/snap/catalog".to_owned(),
                digest('2'),
            )],
            // BORROW: .to_owned() makes the owned text the triple keeps
            inputs: vec![("mapping".to_owned(), "/in/mapping".to_owned(), digest('3'))],
            // BORROW: .to_owned() makes the owned text the pair keeps
            metadata: vec![("plan.model".to_owned(), Value::from("claude-haiku-4-5"))],
        }
    }

    /// The parts a vector's projection names, with the paths made up.
    fn of_projection(projection: &Value) -> Self {
        // INDEX: a projection and each of its members carry every key the closures name
        // BORROW: .clone() makes the list an owned vector
        let list = |key: &str| projection[key].as_array().expect("a list").clone();
        // INDEX: a projection and each of its members carry every key the closures name
        // BORROW: .to_owned() makes the owned text the closure returns
        let text = |value: &Value, key: &str| value[key].as_str().expect("a string").to_owned();
        let refs = |key: &str| -> Vec<(String, String, Digest)> {
            list(key)
                .iter()
                .map(|r| {
                    let digest = text(r, "digest").parse().expect("a digest");
                    (text(r, "kind"), format!("/made/up/{key}"), digest)
                })
                .collect()
        };
        Self {
            // BORROW: .to_owned() makes the owned text the part keeps
            root: "/made/up".to_owned(),
            trace: None,
            raw: Vec::new(),
            artifacts: list("artifacts")
                .iter()
                .map(|a| {
                    let sha256 = text(a, "sha256").parse().expect("a digest");
                    // BORROW: .to_owned() makes the owned text the triple keeps
                    (text(a, "path"), "/made/up/artifact".to_owned(), sha256)
                })
                .collect(),
            snapshots: refs("snapshots"),
            inputs: refs("inputs"),
            // INDEX: every vector projection carries a `metadata` object
            metadata: projection["metadata"]
                .as_object()
                .expect("an object")
                .iter()
                // BORROW: .clone() makes the owned pair the part keeps
                .map(|(path, value)| (path.clone(), value.clone()))
                .collect(),
        }
    }

    fn context(&self) -> RunContext {
        let run = RunKey::new(digest('a'), 1, 1).expect("a run key");
        // BORROW: .clone() hands the builder its own copy of the root
        let mut builder = RunContext::builder().run(run).root(self.root.clone());
        if let Some(trace) = &self.trace {
            // BORROW: .clone() hands the builder its own copy of the trace path
            builder = builder.trace(trace.clone());
        }
        for (stream, path) in &self.raw {
            let stream = StreamName::from_str(stream).expect("a stream name");
            // BORROW: .clone() hands the builder its own copy of the path
            builder = builder.raw(ContextRaw::new(stream, path.clone()));
        }
        for (path, abs, sha256) in &self.artifacts {
            let path = RelPath::from_str(path).expect("a relative path");
            // BORROW: .clone() hands the builder its own copy of the path and the digest
            builder = builder.artifact(ContextArtifact::new(path, abs.clone(), sha256.clone()));
        }
        for (kind, path, digest) in &self.snapshots {
            let kind = Name::from_str(kind).expect("a name");
            // BORROW: .clone() hands the builder its own copy of the path and the digest
            builder = builder.snapshot(ContextRef::new(kind, path.clone(), digest.clone()));
        }
        for (kind, path, digest) in &self.inputs {
            let kind = Name::from_str(kind).expect("a name");
            // BORROW: .clone() hands the builder its own copy of the path and the digest
            builder = builder.input(ContextRef::new(kind, path.clone(), digest.clone()));
        }
        for (path, value) in &self.metadata {
            let path = FieldPath::from_str(path).expect("a field path");
            // BORROW: .clone() hands the value its own copy
            let value = JsonValue::new(value.clone()).expect("a metadata value");
            builder = builder.metadata(path, value);
        }
        builder.build().expect("a context")
    }
}

/// Guards: Cond 7 — the context digest of each oracle case equals the digest
/// Python computes from the RFC 8785 form of the case, however the lists are ordered; a change to
/// `root`, `trace`, `raw`, `scratch` or an absolute path keeps the digest, and a change to an
/// artifact's `sha256`, a snapshot's or an input's digest or a metadata value changes it.
/// Oracle: `context_digest.toml`, generated by Python `rfc8785`, and a hand-written table of
/// edits.
#[test]
fn context_digest_follows_the_oracle_and_ignores_paths() {
    let cases = vectors(CONTEXT_VECTORS);
    assert_eq!(cases.len(), 4);
    for case in &cases {
        // INDEX: every context vector carries `title`, `digest`, `input` and `sorted`
        // BORROW: .as_str() reads the text of a TOML value
        let title = case["title"].as_str().expect("a title");
        // INDEX: every context vector carries `title`, `digest`, `input` and `sorted`
        // BORROW: .as_str() reads the text of a TOML value
        let expected = case["digest"].as_str().expect("a digest");
        for form in ["input", "sorted"] {
            // INDEX: every context vector carries `title`, `digest`, `input` and `sorted`
            // BORROW: .as_str() reads the JSON text of a TOML value
            let text = case[form].as_str().expect("JSON text");
            let projection: Value = serde_json::from_str(text).expect("JSON");
            let context = Parts::of_projection(&projection).context();
            assert_eq!(
                // BORROW: .as_str() compares the digest as text
                context.context_digest().as_str(),
                expected,
                "{title} ({form})"
            );
        }
    }

    let same = |edit: Edit| {
        let mut parts = Parts::base();
        edit(&mut parts);
        parts.context().context_digest()
    };
    let base = Parts::base().context().context_digest();
    let keeps: [(&str, Edit); 6] = [
        // BORROW: .to_owned() makes the owned text the part keeps
        ("root", |p| p.root = "/elsewhere".to_owned()),
        ("trace", |p| p.trace = None),
        ("raw", |p| p.raw.clear()),
        ("artifact abs", |p| {
            // INDEX: the base context holds one member of each part, so index 0 exists
            // BORROW: .to_owned() makes the owned text the triple keeps
            p.artifacts[0].1 = "/other/plan.json".to_owned();
        }),
        ("snapshot path", |p| {
            // INDEX: the base context holds one member of each part, so index 0 exists
            // BORROW: .to_owned() makes the owned text the triple keeps
            p.snapshots[0].1 = "/other/snap".to_owned();
        }),
        ("input path", |p| {
            // INDEX: the base context holds one member of each part, so index 0 exists
            // BORROW: .to_owned() makes the owned text the triple keeps
            p.inputs[0].1 = "/other/in".to_owned();
        }),
    ];
    for (name, edit) in keeps {
        assert_eq!(same(edit), base, "changing {name} keeps the digest");
    }
    let changes: [(&str, Edit); 5] = [
        ("artifact sha256", |p| {
            // INDEX: the base context holds one member of each part, so index 0 exists
            p.artifacts[0].2 = digest('9');
        }),
        ("snapshot digest", |p| {
            // INDEX: the base context holds one member of each part, so index 0 exists
            p.snapshots[0].2 = digest('9');
        }),
        ("input digest", |p| {
            // INDEX: the base context holds one member of each part, so index 0 exists
            p.inputs[0].2 = digest('9');
        }),
        ("metadata value", |p| {
            // INDEX: the base context holds one member of each part, so index 0 exists
            p.metadata[0].1 = Value::from("claude-opus-4");
        }),
        ("metadata path", |p| {
            // INDEX: the base context holds one member of each part, so index 0 exists
            // BORROW: .to_owned() makes the owned text the pair keeps
            p.metadata[0].0 = "plan.other".to_owned();
        }),
    ];
    for (name, edit) in changes {
        assert_ne!(same(edit), base, "changing {name} changes the digest");
    }

    let context = Parts::base().context();
    let params = |scratch: &str| {
        // BORROW: .clone() hands the params their own copy of the context
        // BORROW: .to_owned() makes the owned text the params keep
        EvaluateParams::new(context.clone(), Vec::new(), Vec::new(), scratch.to_owned())
    };
    assert_eq!(
        params("/scratch/a").context.context_digest(),
        params("/scratch/b").context.context_digest(),
        "changing scratch keeps the digest"
    );
}

/// Guards: Cond 7 — the digest of each oracle entry equals the digest Python computes
/// from the RFC 8785 form of `{kind, params, role, depends_on, applies_to}`, and the twin of each
/// entry, which differs only in `id`, `group`, `evaluator` and `deadline_ms`, has the same
/// digest. Oracle: `suite_entry_digest.toml`, generated by Python `rfc8785`.
#[test]
fn suite_entry_digest_follows_the_oracle_and_ignores_names() {
    let cases = vectors(ENTRY_VECTORS);
    assert_eq!(cases.len(), 3);
    for case in &cases {
        // INDEX: every entry vector carries `digest`, `entry` and `twin`
        // BORROW: .as_str() reads the text of a TOML value
        let expected = case["digest"].as_str().expect("a digest");
        for form in ["entry", "twin"] {
            // INDEX: every entry vector carries `digest`, `entry` and `twin`
            // BORROW: .as_str() reads the JSON text of a TOML value
            let text = case[form].as_str().expect("JSON text");
            let entry: SuiteEntry = serde_json::from_str(text).expect("an entry");
            // BORROW: .as_str() compares the digest as text
            assert_eq!(entry.digest().as_str(), expected, "{} ({form})", entry.id());
        }
    }

    // `applies_to` keeps its written order: reversing a list of two conditions changes the
    // digest. The count is the positive control that the oracle holds such an entry.
    let mut reversed = 0;
    for case in &cases {
        // INDEX: every entry vector carries `digest`, `entry` and `twin`
        // BORROW: .as_str() reads the text of a TOML value
        let expected = case["digest"].as_str().expect("a digest");
        // INDEX: every entry vector carries `digest`, `entry` and `twin`
        // BORROW: .as_str() reads the JSON text of a TOML value
        let text = case["entry"].as_str().expect("JSON text");
        let mut value: Value = serde_json::from_str(text).expect("JSON");
        let Some(conditions) = value.get_mut("applies_to").and_then(Value::as_array_mut) else {
            continue;
        };
        if conditions.len() < 2 {
            continue;
        }
        conditions.reverse();
        let entry: SuiteEntry = serde_json::from_value(value).expect("an entry");
        // BORROW: .as_str() compares the digest as text
        assert_ne!(entry.digest().as_str(), expected, "{}", entry.id());
        reversed += 1;
    }
    assert_eq!(reversed, 1, "one oracle entry has two conditions");
}
